
let moving=false,playing=false,muted=false,corner='bottom-right';const player=document.querySelector('.mini-player');async function command(action,extra={}){try{await r2.request('media.pip.command',{sessionId:'demo-video',action,...extra},()=>true);return true}catch(e){r2.toast(e.message);return false}}document.getElementById('move').onclick=()=>{moving=!moving;document.getElementById('move-hint').textContent=moving?'Move mode · D-pad chooses corner · Select keeps it · Back cancels':'Position kept'};let oldCorner=corner;const original=window.omniMediaController;window.omniMediaController=window.omniPadController=a=>{if(!moving)return original(a);if(['left','right','up','down'].includes(a)){let [v,h]=corner.split('-');if(a==='left'||a==='right')h=a;else v=a==='up'?'top':'bottom';corner=v+'-'+h;player.dataset.corner=corner;document.getElementById('move-hint').textContent='Corner: '+corner;return true}if(a==='cross'){moving=false;oldCorner=corner;command('place',{corner});document.getElementById('move-hint').textContent='Position kept';return true}if(a==='circle'){moving=false;corner=oldCorner;player.dataset.corner=corner;document.getElementById('move-hint').textContent='Move cancelled';return true}return false};document.getElementById('play').onclick=async()=>{if(await command(playing?'pause':'play')){playing=!playing;document.getElementById('play').textContent=playing?'Pause':'Play';document.getElementById('player-status').textContent=(playing?'Playing':'Paused')+' · 01:24'}};document.getElementById('mute').onclick=async()=>{if(await command('mute',{muted:!muted})){muted=!muted;document.getElementById('mute').textContent=muted?'Unmute':'Mute'}};document.getElementById('restore').onclick=()=>command('restore');document.getElementById('close').onclick=async()=>{if(await command('close')){player.hidden=true;document.getElementById('move').disabled=true;r2.toast('Mini player closed in preview.')}};